function aiSave(){localStorage.setItem("cmd-ai-history",JSON.stringify(aiHistory.slice(-30)))}

function aiMsg(role,text,save=true){
 const d=document.createElement("div"); d.className="msg "+role; d.textContent=text; aiMessages.appendChild(d);
 aiMessages.scrollTop=aiMessages.scrollHeight;
 if(save){aiHistory.push({role,text}); aiSave()}
}
function aiRenderHistory(){
 aiMessages.innerHTML="";
 if(!aiHistory.length) aiMsg("ai","I can explain commands, summarize a category, build analysis flows, cross-function maps, safe reverse-engineering steps, Android/iOS root-jailbreak detection checks, and LLM jailbreak/prompt-injection defences.",false);
 else aiHistory.forEach(m=>aiMsg(m.role,m.text,false));
}
function tokens(s){return (String(s||"").toLowerCase().match(/[a-z0-9_.$/+:-]{2,}/g)||[]).filter(x=>!["the","and","for","with","this","that","how","what","use","from"].includes(x))}
function scoreCard(x,q){
 const ts=tokens(q); if(!ts.length)return 0;
 const hay=[x.cat,x.os,x.cmd,x.title,x.meaning,x.when,x.example,x.result,x.apply,x.sample,x.interpret,x.analysis,x.crossfunction,x.reverse,x.defence,x.layer,x.evidence].join(" ").toLowerCase();
 let s=0; ts.forEach(t=>{if(hay.includes(t))s+=t.length>5?3:1}); return s;
}
function topCards(q,n=5){
 return DATA.map(x=>[scoreCard(x,q),x]).filter(z=>z[0]>0).sort((a,b)=>b[0]-a[0]).slice(0,n).map(z=>z[1]);
}
function cardBrief(x){
 return `${x.title} [${x.cat}${x.level?" · "+x.level:""}]\nCommand/workflow: ${x.cmd}\nUse: ${x.when||x.meaning}\nExpected: ${x.result}${x.interpret?`\nInterpret: ${x.interpret}`:""}${x.defence?`\nDefence: ${x.defence}`:""}`;
}
function currentPool(){
 let rows=filtered(); return rows.length?rows:DATA;
}
function summarizeRows(rows){
 const cats={}; rows.forEach(x=>cats[x.cat]=(cats[x.cat]||0)+1);
 const top=Object.entries(cats).sort((a,b)=>b[1]-a[1]).slice(0,7);
 const levels={}; rows.forEach(x=>{if(x.level)levels[x.level]=(levels[x.level]||0)+1});
 return `Summary of ${rows.length} cards\nCategories: ${top.map(([k,v])=>`${k} (${v})`).join(", ")}\nLevels: ${Object.entries(levels).map(([k,v])=>`${k} ${v}`).join(", ")||"mixed"}\nLearning flow: INPUT → COMMAND/TOOL → OUTPUT → INTERPRETATION → LAYER → HYPOTHESIS → SAFE TEST → FIX → RETEST.`;
}
function analysisFlow(x){
 return `ANALYSE\n1. INPUT — identify exact input/state.\n2. PROCESS — run/inspect: ${x.cmd}\n3. OUTPUT — expected: ${x.result}\n4. INTERPRET — ${x.interpret||x.meaning}\n5. LAYER — ${x.layer||x.cat}\n6. HYPOTHESIS — explain one testable cause.\n7. SAFE TEST — ${x.sample||x.example}\n8. EVIDENCE — ${x.evidence||"capture command, output, timestamp and affected asset"}\n9. FIX/CONTROL — ${x.defence||"apply the smallest reversible correction"}\n10. RETEST — repeat the same observation and compare before/after.`;
}
function crossFlow(x){
 return `CROSSFUNCTION\nTARGET: ${x.title}\n→ CALLERS/CALLEES: identify who invokes/consumes it\n→ DATA: ${x.apply||"inputs and state"}\n→ API/PROCESS: ${x.cmd}\n→ STORAGE/FILES: check config, cache, logs, artifacts\n→ UI/OUTPUT: ${x.result}\n→ TEST: reproduce expected vs actual\n→ BUILD/DEPLOY: verify artifact/version/hash\n→ RUNTIME: verify process, logs and environment\nLikely layer: ${x.layer||x.cat}\nEvidence goal: ${x.evidence||"two independent signals where practical"}.`;
}
function reverseFlow(x){
 return `REVERSE / EFFECT-FIRST\nEFFECT → timestamp → process/PID → module/file → function/symbol → input/state → decision/branch → output.\nStart from: ${x.title}\nUseful observation: ${x.cmd}\nInterpretation: ${x.interpret||x.meaning}\nCross-check: ${x.evidence||"runtime log + static/source evidence"}\nRule: decompiler/string/tool output is a hypothesis until corroborated. Work only on your own or explicitly authorized software.`;
}
function rootFlow(){
 return `MOBILE ROOT/JAILBREAK DETECTION (detection only)\n1. Record device/build metadata.\n2. Check shell identity: adb shell id\n3. Check build signals: ro.debuggable, ro.build.tags\n4. Check whether su is discoverable: adb shell which su\n5. Review installed-package inventory against your approved indicator list.\n6. Add platform attestation/app integrity where appropriate.\n7. Score multiple signals; log the exact trigger.\n8. Investigate false positives by replaying each signal.\nDo not treat a single property/package as conclusive, and do not use detection checks to bypass device security.`;
}
function llmFlow(){
 return `LLM JAILBREAK / PROMPT-INJECTION DEFENCE\n1. Label user/retrieved/tool content as untrusted data.\n2. Keep authorization and secrets outside prompt secrecy.\n3. Minimize tool functionality, permissions and autonomy.\n4. Validate tool name + arguments against an allow-list.\n5. Require approval/system verification for high-impact actions.\n6. Validate model output with schemas/policy before any sink.\n7. Contextually encode output for HTML/SQL/files/logs.\n8. Use fake canaries—not real credentials—for leakage tests.\n9. Log provenance, tool calls, evidence and outcome.\n10. Regression-test direct, indirect, memory and tool-output injection paths.`;
}

function inputOutputFlow(x){return x?`INPUT / OUTPUT\nINPUT: ${x.apply||x.when}\nPROCESS: ${x.cmd}\nOUTPUT: ${x.result}\nINTERPRET: ${x.interpret||x.meaning}\nLAYER: ${x.layer||x.topic}\nEVIDENCE: ${x.evidence||"capture input, output and timestamp"}`:`INPUT → PROCESS → DECISION → STATE/STORAGE → OUTPUT → LOG → VALIDATION`;}
function crosscheckFlow(x){return x?`CROSSCHECK: ${x.title}\n1 Primary: ${x.example}\n2 Expected: ${x.result}\n3 Independent evidence: ${x.evidence||"use a second tool/source"}\n4 Cross-function: ${x.crossfunction||"trace caller → data → process → output"}\n5 Recheck: ${x.recheck||"repeat the same observation after change"}\n6 Falsify: what evidence would contradict the hypothesis?`:`CROSSCHECK\nidentity/path/version/hash → second independent source → config vs runtime → expected vs actual → contradictions → same-test retest`;}
function methodFlow(){return `AUTHORIZED SECURITY METHOD\nAUTHORIZE → SCOPE/ROE → PASSIVE REVIEW → INVENTORY → SAFE VALIDATION → EVIDENCE → ROOT CAUSE → FIX/CONTROL → RETEST → REPORT.\nFor each approved test add a detection checkpoint: what log or alert should exist? Preserve evidence; do not erase logs or install persistence.`;}
function sourceFlow(){const n=[...new Set(DATA.map(x=>x.source).filter(Boolean))];return `SOURCE LABELS (${n.length})\n`+n.slice(0,30).map(x=>"• "+x).join("\n")+(n.length>30?`\n…plus ${n.length-30} more.`:"");}

function detectLanguage(q){
 q=q.toLowerCase();
 if(q.includes("python"))return "python";
 if(q.includes("powershell"))return "powershell";
 if(q.includes("bash")||q.includes("shell script"))return "bash";
 if(q.includes("php"))return "php";
 if(q.includes("kotlin")||q.includes("android code"))return "kotlin";
 if(q.includes("java")&&!q.includes("javascript"))return "java";
 if(q.includes("c++")||q.includes("cpp"))return "cpp";
 if(/\bc\b/.test(q)&&q.includes("code"))return "c";
 if(q.includes("sql"))return "sql";
 if(q.includes("css"))return "css";
 if(q.includes("html")||q.includes("web page"))return "html";
 return "javascript";
}
function codeTemplate(lang,task){
 const t=(task||"example").trim();
 const safe=t.replace(/[`$]/g,"").slice(0,120);
 const map={
 javascript:`// ${safe}\nfunction main(input) {\n  // Validate input first\n  if (input == null) throw new Error("input required");\n  return { ok: true, value: input };\n}\n\nconsole.log(main("demo"));`,
 python:`# ${safe}\ndef main(value):\n    if value is None:\n        raise ValueError("value is required")\n    return {"ok": True, "value": value}\n\nif __name__ == "__main__":\n    print(main("demo"))`,
 bash:`#!/usr/bin/env bash\nset -euo pipefail\n# ${safe}\ninput="\${1:-demo}"\nprintf 'input=%s\\n' "$input"`,
 powershell:`# ${safe}\nparam([string]$InputValue = "demo")\nif ([string]::IsNullOrWhiteSpace($InputValue)) { throw "InputValue is required" }\n[pscustomobject]@{ ok = $true; value = $InputValue }`,
 php:`<?php\n// ${safe}\nfunction main($value) {\n    if ($value === null) { throw new InvalidArgumentException("value required"); }\n    return ["ok" => true, "value" => $value];\n}\nprint_r(main("demo"));`,
 sql:`-- ${safe}\n-- Parameterized-query pattern\nSELECT id, name\nFROM items\nWHERE name = ?\nORDER BY id DESC;`,
 html:`<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<title>Demo</title>\n<style>body{font-family:system-ui;padding:24px} .card{padding:16px;border:1px solid #ccc;border-radius:12px}</style>\n</head>\n<body><div class="card"><h1>${safe||"Demo"}</h1><p>Responsive local example.</p></div></body>\n</html>`,
 css:`/* ${safe} */\n.card {\n  display: grid;\n  gap: 12px;\n  padding: 16px;\n  border: 1px solid currentColor;\n  border-radius: 12px;\n}\n@media (max-width: 640px) {\n  .card { padding: 12px; }\n}`,
 java:`// ${safe}\npublic class Main {\n  static String mainValue(String value) {\n    if (value == null) throw new IllegalArgumentException("value required");\n    return value;\n  }\n  public static void main(String[] args) {\n    System.out.println(mainValue("demo"));\n  }\n}`,
 kotlin:`// ${safe}\nfun mainValue(value: String?): String {\n    require(!value.isNullOrBlank()) { "value required" }\n    return value\n}\nfun main() {\n    println(mainValue("demo"))\n}`,
 c:`/* ${safe} */\n#include <stdio.h>\n#include <string.h>\nint main(void) {\n    const char *value = "demo";\n    if (strlen(value) == 0) return 1;\n    printf("value=%s\\n", value);\n    return 0;\n}`,
 cpp:`// ${safe}\n#include <iostream>\n#include <string>\nint main() {\n    std::string value = "demo";\n    if (value.empty()) return 1;\n    std::cout << "value=" << value << "\\n";\n    return 0;\n}`
 };
 return map[lang]||map.javascript;
}
function faqAnswer(q){
 const l=q.toLowerCase();
 if(l.includes("difference")&&l.includes("grep")&&l.includes("find"))return "`find` searches filesystem entries by attributes/name; `grep` searches text content. A common workflow is find files first, then grep content.";
 if(l.includes("what is")&&l.includes("crosscheck"))return "Crosscheck means verifying the same claim with a second independent evidence source. Example: port → PID with ss/netstat, then PID → process with ps/Get-Process.";
 if(l.includes("what is")&&l.includes("recheck"))return "Recheck means repeating the original test after one controlled change, then running related regression checks and verifying the running artifact/version.";
 if(l.includes("root")||l.includes("jailbreak"))return rootFlow();
 if(l.includes("prompt injection")||l.includes("llm jailbreak"))return llmFlow();
 return null;
}
function structuralVirtualTest(lang,code){
 const lines=code.split(/\r?\n/),result=[];
 if(!code.trim())return "No code to test.";
 result.push(`Language: ${lang}`);
 result.push(`Lines: ${lines.length}`);
 if(lang==="javascript"){
   try{new Function(code);result.push("Syntax: PASS")}catch(e){result.push("Syntax: FAIL — "+e.message)}
 } else if(lang==="html"){
   const doc=new DOMParser().parseFromString(code,"text/html");
   result.push(`HTML elements: ${doc.querySelectorAll("*").length}`);
   result.push("Parse: PASS (browser DOM parser)");
 } else if(lang==="css"){
   let opens=(code.match(/{/g)||[]).length,closes=(code.match(/}/g)||[]).length;
   result.push(`Brace balance: ${opens===closes?"PASS":"CHECK"} (${opens}/${closes})`);
 } else {
   const pairs=[["(",")"],["{","}"],["[","]"]];
   pairs.forEach(([a,b])=>{const x=(code.split(a).length-1),y=(code.split(b).length-1);result.push(`${a}${b} balance: ${x===y?"PASS":"CHECK"} (${x}/${y})`)});
   result.push("Runtime: simulated only in this offline HTML; use the language's real compiler/interpreter for verification.");
 }
 if(/eval\s*\(|shell\s*=\s*true|innerHTML\s*=/.test(code))result.push("Review note: code contains a potentially unsafe interpretation boundary; validate inputs and prefer safer APIs.");
 return result.join("\n");
}
function codeAnswer(q){
 const lang=detectLanguage(q),task=q.replace(/^\/code\s*/i,"")||"example";
 return `CODE DRAFT (${lang})\n${codeTemplate(lang,task)}\n\nNext: open Code Studio to edit/explain/test. For security-sensitive requests I will keep examples defensive, local, and authorized.`;
}

function reasonLikeAnalyst(q,x){
 const target=x||topCards(q,1)[0];
 if(!target)return "ANALYST LOOP\nGOAL → known facts → unknowns → hypotheses → evidence needed → safest test → result → update hypothesis → next action.";
 return `ANALYST WORKFLOW
GOAL: ${q}
KNOWN: ${target.meaning}
INPUT/CONTEXT: ${target.apply||target.when}
HYPOTHESIS: ${target.analysis||"identify the earliest plausible divergence"}
EVIDENCE NEEDED: ${target.evidence||"two independent observations where practical"}
SAFE TEST: ${target.sample||target.example}
CROSSCHECK: ${target.crossfunction||"compare static/config evidence with runtime evidence"}
FALSIFY: what result would prove the hypothesis wrong?
RECHECK: ${target.recheck||"repeat the same test after one controlled change"}
NEXT: update the hypothesis only from new evidence, not confidence alone.`;
}
function vizNodes(mode,x,q){
 if(mode==="cross")return [
  ["TARGET",x?.title||q],
  ["CALLERS",x?.crossfunction||"Who invokes/consumes this?"],
  ["DATA",x?.apply||"Input/state"],
  ["PROCESS",x?.cmd||"Function/tool"],
  ["STORAGE/API","Files, state, dependencies"],
  ["OUTPUT",x?.result||"Observable result"],
  ["TEST",x?.sample||x?.example||"Safe reproduction"],
  ["RUNTIME",x?.evidence||"Logs/process/artifact identity"]
 ];
 if(mode==="reverse")return [
  ["EFFECT",x?.result||q],
  ["TIME","Exact timestamp / reproduction"],
  ["PROCESS","PID / package / executable"],
  ["MODULE","Binary / library / source file"],
  ["FUNCTION","Symbol / function / handler"],
  ["INPUT",x?.apply||"Original input/state"],
  ["DECISION",x?.analysis||"Branch / validation / lookup"],
  ["ROOT CAUSE",x?.reverse||"First proven divergence"]
 ];
 if(mode==="evidence")return [
  ["CLAIM",x?.title||q],
  ["STATIC",x?.cmd||"Structure/source/config"],
  ["RUNTIME",x?.sample||x?.example||"Observed behavior"],
  ["IDENTITY","Hash · version · path · timestamp"],
  ["CROSSCHECK",x?.crossfunction||"Independent evidence"],
  ["CONTRADICTION","What would prove the claim wrong?"],
  ["RECHECK",x?.recheck||"Repeat same test"],
  ["CONCLUSION",x?.interpret||x?.meaning||"Evidence-based conclusion"]
 ];
 return [
  ["INPUT",x?.apply||q],
  ["PARSE / LOAD","Decode, validate, normalize"],
  ["PROCESS",x?.cmd||"Function / command"],
  ["STATE",x?.analysis||"Relevant values/config"],
  ["DECISION","Branch / lookup / policy"],
  ["OUTPUT",x?.result||"Result / error / log"],
  ["EVIDENCE",x?.evidence||"Capture result + timestamp"],
  ["RETEST",x?.recheck||"Same input after correction"]
 ];
}
function renderVisualization(mode,x,q){
 const nodes=vizNodes(mode,x,q);
 vizCanvas.innerHTML=`<div class="viz-flow">${nodes.map((n,i)=>`${i?'<span class="viz-arrow">→</span>':''}<div class="viz-node"><b>${safeEsc(n[0])}</b><div>${safeEsc(n[1])}</div></div>`).join("")}</div>`;
 vizNote.textContent=`Mode: ${mode} · Context: ${x?.title||q||"general analysis"} · Generated locally from handbook fields and analysis rules.`;
}
function openVisualization(mode="flow",x=aiCard,q=""){
 vizPanel.classList.add("open");vizMode.value=mode;vizTopic.value=q||x?.title||"";renderVisualization(mode,x,q);
}
function followups(mode){
 const sets={
  base:["/summary","/reason","/visualize","/evidence","/code javascript","/studio","/test","/analyze","/crosscheck","/reverse","/rootcheck"],
  reverse:["Show related binary commands","Crossfunction this","What evidence proves it?","Next safe step"],
  root:["Android signals","False positive analysis","App-side architecture","Summary"],
  llm:["Prompt injection flow","Tool permissions","Output handling","Canary test"]
 };
 const arr=sets[mode]||sets.base;
 aiSuggest.innerHTML=arr.map(t=>`<button data-aiq="${safeEsc(t)}">${safeEsc(t)}</button>`).join("");
}
function aiAnswer(q){
 const low=q.trim().toLowerCase();
 const c=aiCard;
 if(!low)return "Type a question or choose a follow-up.";
 if(low==="/help"||low.includes("what can you do")) return "Commands: /summary, /reason, /visualize [flow|cross|reverse|evidence], /evidence, /faq, /code <language/task>, /studio, /test, /inputoutput, /analyze, /crossfunction, /crosscheck, /recheck, /reverse, /method, /rootcheck, /llmguard, /sources, /next. You can also ask natural-language questions such as “analyse adb logcat”, “how do I verify a config change?”, or “show safe reverse-engineering flow”.";
 if(low==="/summary"||low.includes("summary")) return c?`Selected card\n${cardBrief(c)}\n\n${summarizeRows(topCards(c.title+" "+c.cat,8))}`:summarizeRows(currentPool());
 if(low==="/analyze"||low==="/analyse"||low.includes("analyse this")||low.includes("analyze this")) return c?analysisFlow(c):"Select a card with its AI button, or ask “analyse <command/topic>”.";
 if(low==="/crossfunction"||low.includes("crossfunction")||low.includes("cross-function")) return c?crossFlow(c):`CROSSFUNCTION TEMPLATE\nTARGET → CALLERS/CALLEES → DATA → API/PROCESS → STORAGE → UI/OUTPUT → TEST → BUILD → RUNTIME.\nAsk about a command/topic or select a card to specialize this map.`;
 if(low==="/reason"||low.includes("think through")||low.includes("reason this"))return reasonLikeAnalyst(q,c);
 if(low.startsWith("/visualize")||low.includes("visualise")||low.includes("visualize")){
   let mode=low.includes("cross")?"cross":low.includes("reverse")?"reverse":low.includes("evidence")?"evidence":"flow";
   openVisualization(mode,c,q.replace(/^\/visualize\s*/i,""));return `Visualization opened in ${mode} mode.`;
 }
 if(low==="/evidence"||low.includes("evidence map")){openVisualization("evidence",c,q);return c?`Evidence view opened for ${c.title}.`:"Evidence visualization opened.";}
 if(low==="/studio"||low.includes("open code studio")){openStudio();return "Code Studio opened. Choose a language, describe the task, then Draft. HTML/CSS/JavaScript can be tested in the local network-blocked sandbox.";}
 if(low.startsWith("/code")||low.includes("write code")||low.includes("create code")||low.includes("generate code"))return codeAnswer(q);
 if(low==="/faq"){return "FAQ examples: What is crosscheck? What is recheck? Difference between grep and find? How does root/jailbreak detection work? What is prompt injection?"; }
 const fq=faqAnswer(q);if(fq)return fq;
 if(low==="/test"||low.includes("virtual test"))return c?`VIRTUAL TEST PLAN\n1. Input: ${c.apply||c.when}\n2. Execute/observe: ${c.example}\n3. Expected: ${c.result}\n4. Crosscheck: ${c.evidence||"second independent observation"}\n5. Recheck after one controlled change.\nThis local assistant can structurally test code in Code Studio; actual OS/device commands still require the real platform.`:"Open Code Studio for local code checks, or select a card for a command-specific virtual test plan.";
 if(low==="/inputoutput"||low.includes("input/output")||low.includes("input output")) return inputOutputFlow(c);
 if(low==="/crosscheck"||low.includes("cross-check")||low.includes("crosscheck")) return crosscheckFlow(c);
 if(low==="/recheck"||low.includes("recheck")) return c?`RECHECK\nBASELINE → ONE REVERSIBLE CHANGE → SAME TEST → RELATED REGRESSION TESTS → RUNTIME/ARTIFACT VERIFY\n${c.recheck||"Repeat the original observation and compare before/after evidence."}`:"RECHECK\nBASELINE → ONE CHANGE → SAME TEST → REGRESSION → RUNTIME VERIFY";
 if(low==="/method"||low.includes("ethical method")||low.includes("assessment method")) return methodFlow();
 if(low==="/sources"||low.includes("ebook sources")||low.includes("source list")) return sourceFlow();
 if(low==="/reverse"||low.includes("reverse engineering")||low.includes("reverse flow")) {followups("reverse"); return c?reverseFlow(c):"EFFECT → TIME → PID → MODULE → FUNCTION → INPUT → DECISION → OUTPUT.\nSearch/select a binary, APK, process, log, or source card and I will map the safe effect-first workflow."; }
 if(low==="/rootcheck"||low.includes("jailbreak detection")||low.includes("root detection")||low.includes("rootcheck")) {followups("root"); return rootFlow();}
 if(low==="/llmguard"||low.includes("prompt injection")||low.includes("llm jailbreak")||low.includes("jailbreak defence")||low.includes("jailbreak defense")) {followups("llm"); return llmFlow();}
 if(low==="/detect"||low.includes("detection flow")) return `DETECTION FLOW\nBASELINE → OBSERVE → COLLECT EVIDENCE → CORRELATE TIME/PROCESS/FILE/NETWORK → HYPOTHESIS → SAFE VALIDATION → ROOT CAUSE → CONTROL → RETEST.\nFor mobile use /rootcheck; for LLM jailbreak defence use /llmguard.`;
 if(low==="/next") return c?`Next safe actions for ${c.title}:\n1. Capture baseline/evidence.\n2. Run the least-invasive observation: ${c.example}\n3. Compare output with expected: ${c.result}\n4. If different, use: ${c.crossfunction||"cross-function tracing"}\n5. Apply the smallest reversible fix/control.\n6. Repeat the same test.`:"Select a card first.";
 const hits=topCards(q,5);
 if(!hits.length) return "I did not find a strong match in the handbook. Try a command name, OS, layer, error text, “reverse engineering”, “root detection”, or “LLM jailbreak defence”.";
 return `Best matches:\n\n${hits.map((x,i)=>`${i+1}. ${cardBrief(x)}`).join("\n\n")}\n\nFollow-up: select a card's AI button for /analyze, /crossfunction, or /reverse.`;
}
function aiSend(q){
 q=(q??aiText.value).trim(); if(!q)return;
 aiMsg("user",q); aiText.value="";
 const ans=aiAnswer(q); aiMsg("ai",ans);
 if(!q.toLowerCase().includes("root")&&!q.toLowerCase().includes("jailbreak")&&!q.toLowerCase().includes("reverse")) followups("base");
}
