/* ---------- Code Studio ---------- */
const codeStudio=$("#codeStudio"),studioLang=$("#studioLang"),studioTask=$("#studioTask"),studioCode=$("#studioCode"),studioOutput=$("#studioOutput"),studioFrame=$("#studioFrame");
function openStudio(){
 codeStudio.classList.add("open");
 if(!studioCode.value.trim())studioCode.value=codeTemplate(studioLang.value,studioTask.value||"starter example");
}
$("#studioClose").onclick=()=>codeStudio.classList.remove("open");
$("#studioFull").onclick=()=>codeStudio.classList.toggle("fullpage");
$("#studioGenerate").onclick=()=>{
 studioCode.value=codeTemplate(studioLang.value,studioTask.value||"starter example");
 studioOutput.textContent=`Drafted ${studioLang.value} template. Review and adapt it to your actual requirements.`;
 studioFrame.classList.remove("visible");
};
$("#studioClear").onclick=()=>{studioCode.value="";studioOutput.textContent="Cleared.";studioFrame.classList.remove("visible")};
$("#studioCopy").onclick=()=>copyTextValue(studioCode.value,"Code copied");
$("#studioExplain").onclick=()=>{
 const code=studioCode.value,lang=studioLang.value;
 studioOutput.textContent=`EXPLANATION\nLanguage: ${lang}\nPurpose: ${studioTask.value||"user-provided code"}\nStructure: input/validation → main processing → output.\nLines: ${code.split(/\r?\n/).length}\nCrosscheck: verify inputs, error paths, side effects, and expected output before deployment.`;
};
$("#studioTest").onclick=()=>{
 const lang=studioLang.value,code=studioCode.value;
 studioOutput.textContent=structuralVirtualTest(lang,code);
 studioFrame.classList.remove("visible");
 if(lang==="html"){
   const blocked=`<meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src data:; style-src 'unsafe-inline'; script-src 'unsafe-inline'; connect-src 'none'; media-src 'none'; frame-src 'none'">`;
   studioFrame.srcdoc=blocked+code;studioFrame.classList.add("visible");
 }else if(lang==="css"){
   const safeText=code.replace(/<\/style/gi,"<\\/style");
   studioFrame.srcdoc=`<meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; connect-src 'none'"><style>${safeText}</style><div class="card">CSS preview card</div>`;
   studioFrame.classList.add("visible");
 }else if(lang==="javascript"){
   const escaped=code.replace(/<\/script/gi,"<\\/script");
   studioFrame.srcdoc=`<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; connect-src 'none'"><pre id=o></pre><script>const o=document.getElementById('o');const old=console.log;console.log=(...a)=>o.textContent+=a.join(' ')+'\\n';try{${escaped}}catch(e){o.textContent+='ERROR: '+e.message}<\\/script>`;
   studioFrame.classList.add("visible");
 }
};
