/* draggable + resizable bubble */
let bubbleDrag=null,bubbleResizeState=null,panelDrag=null,panelResizeState=null;
aiBubble.addEventListener("pointerdown",e=>{
 if(e.target.closest("#aiBubbleResize")) return;
 const r=aiBubble.getBoundingClientRect();
 bubbleDrag={x:e.clientX,y:e.clientY,l:r.left,t:r.top,moved:false};
 aiBubble.dataset.dragging="0";
 aiBubble.setPointerCapture(e.pointerId);
});
aiBubble.addEventListener("pointermove",e=>{
 if(!bubbleDrag)return;
 const dx=e.clientX-bubbleDrag.x,dy=e.clientY-bubbleDrag.y;
 if(Math.abs(dx)>3||Math.abs(dy)>3){bubbleDrag.moved=true;aiBubble.dataset.dragging="1";}
 aiBubble.style.left=(bubbleDrag.l+dx)+"px";
 aiBubble.style.top=(bubbleDrag.t+dy)+"px";
 aiBubble.style.right="auto";aiBubble.style.bottom="auto";
 clampBubble();
});
function endBubbleDrag(){if(!bubbleDrag)return;clampBubble();saveBubbleState();setTimeout(()=>aiBubble.dataset.dragging="0",60);bubbleDrag=null;}
aiBubble.addEventListener("pointerup",endBubbleDrag);
aiBubble.addEventListener("pointercancel",endBubbleDrag);

aiBubbleResize.addEventListener("pointerdown",e=>{
 e.stopPropagation(); e.preventDefault();
 bubbleResizeState={x:e.clientX,y:e.clientY,size:aiBubble.getBoundingClientRect().width};
 aiBubble.dataset.resizing="1";
 aiBubbleResize.setPointerCapture(e.pointerId);
});
aiBubbleResize.addEventListener("pointermove",e=>{
 if(!bubbleResizeState)return;
 const dx=e.clientX-bubbleResizeState.x,dy=e.clientY-(bubbleResizeState.y||e.clientY);
 const delta=(dx+dy)/2;
 applyBubbleSize(bubbleResizeState.size+delta);clampBubble();
});
function endBubbleResize(){if(!bubbleResizeState)return;clampBubble();saveBubbleState();aiBubble.dataset.resizing="0";bubbleResizeState=null;}
aiBubbleResize.addEventListener("pointerup",endBubbleResize);
aiBubbleResize.addEventListener("pointercancel",endBubbleResize);

/* draggable + resizable panel */
aiHead.addEventListener("pointerdown",e=>{
 if(e.target.closest("button")||aiPanel.classList.contains("fullpage")) return;
 const r=aiPanel.getBoundingClientRect();
 panelDrag={x:e.clientX,y:e.clientY,l:r.left,t:r.top};
 aiHead.setPointerCapture(e.pointerId);
});
aiHead.addEventListener("pointermove",e=>{
 if(!panelDrag)return;
 const dx=e.clientX-panelDrag.x,dy=e.clientY-panelDrag.y;
 aiPanel.style.left=(panelDrag.l+dx)+"px";
 aiPanel.style.top=(panelDrag.t+dy)+"px";
 aiPanel.style.right="auto";aiPanel.style.bottom="auto";
 normalizePanel(false);
});
function endPanelDrag(){if(!panelDrag)return;normalizePanel(false);savePanelState();panelDrag=null;}
aiHead.addEventListener("pointerup",endPanelDrag);
aiHead.addEventListener("pointercancel",endPanelDrag);

aiResize.addEventListener("pointerdown",e=>{
 if(aiPanel.classList.contains("fullpage"))return;
 e.preventDefault();
 const rect=aiPanel.getBoundingClientRect();
 panelResizeState={x:e.clientX,y:e.clientY,w:rect.width,h:rect.height};
 aiResize.setPointerCapture(e.pointerId);
});
aiResize.addEventListener("pointermove",e=>{
 if(!panelResizeState)return;
 const dx=e.clientX-panelResizeState.x,dy=e.clientY-panelResizeState.y;
 const v=viewportBox();
 const w=Math.max(260,Math.min(v.width-16,panelResizeState.w+dx));
 const h=Math.max(240,Math.min(v.height-16,panelResizeState.h+dy));
 aiPanel.style.width=w+"px"; aiPanel.style.height=h+"px";
 normalizePanel(false);
});
function endPanelResize(){if(!panelResizeState)return;normalizePanel(false);savePanelState();panelResizeState=null;}
aiResize.addEventListener("pointerup",endPanelResize);
aiResize.addEventListener("pointercancel",endPanelResize);

/* auto-hide bottom dock */
const dock=document.querySelector(".dock");
let dockTimer=null,lastY=window.scrollY||0;
function showDock(temp=true){
 document.body.classList.remove("dock-hidden");
 if(temp) scheduleDockHide();
}
function hideDock(){
 if(document.body.classList.contains("mobile-side-open")) return;
 if(aiPanel.classList.contains("open")) return;
 document.body.classList.add("dock-hidden");
}
function scheduleDockHide(){
 clearTimeout(dockTimer);
 dockTimer=setTimeout(()=>hideDock(),2200);
}
window.addEventListener("scroll",()=>{
 const y=window.scrollY||0;
 if(y<18 || y < lastY-8) showDock(true);
 else if(y > lastY+12) hideDock();
 lastY=y;
},{passive:true});
document.addEventListener("pointermove",e=>{if(window.innerHeight-e.clientY<92) showDock(true)},{passive:true});
document.addEventListener("pointerdown",e=>{if(e.target.closest(".dock")) showDock(true)},{passive:true});
dock.addEventListener("click",()=>showDock(true),{passive:true});
dock.addEventListener("touchstart",()=>showDock(true),{passive:true});

applyAiFontSize(localStorage.getItem("cmd-ai-font-size")||11);
applyBubbleSize(localStorage.getItem("cmd-ai-bubble-size")||56);
loadBubbleState();
loadPanelState();
clampBubble();
normalizePanel(true);
aiRenderHistory(); followups("base");

function reflowFloatingUi(){
 clampBubble();
 normalizePanel(true);
 saveBubbleState();
 savePanelState();
 showDock(true);
}
window.addEventListener("resize",reflowFloatingUi);
window.visualViewport?.addEventListener("resize",reflowFloatingUi);
window.visualViewport?.addEventListener("scroll",()=>{if(aiPanel.classList.contains("open"))normalizePanel(true);clampBubble();});

